 void Number(W.Panel parent,string key,string label,bool subscribe=false){var spec=plugin.Descriptor.Parameters.Single(p=>p.Name==key);var panel=new W.DockPanel();if(subscribe){var link=Button("↗",()=>{context.PickSubscription?.Invoke(this,key,true,spec.Kind==ParameterKind.Integer?DataKind.Integer:DataKind.Number);Build();},"Subscribe"+key);W.DockPanel.SetDock(link,W.Dock.Right);panel.Children.Add(link);}var edit=new VisionPlugins.ImageSource.AcquisitionNumericControl{Name=key,Minimum=spec.Minimum??-double.MaxValue,Maximum=spec.Maximum??double.MaxValue,Integer=spec.Kind==ParameterKind.Integer,Text=spec.Kind==ParameterKind.Integer?values[key].GetInt32().ToString(CultureInfo.InvariantCulture):values[key].GetDouble().ToString("F3",CultureInfo.InvariantCulture),Foreground=new SolidColorBrush(Color.FromRgb(98,103,108))};edit.ValueChanged+=value=>{if(building||closed)return;if(spec.Kind==ParameterKind.Integer)Set(key,checked((int)value));else Set(key,(double)(float)value);if(key is "RotPointTotalNum" or "CalibPointTotalNum")Build();};panel.Children.Add(edit);Row(parent,label,panel);}
 void Toggle(W.Panel parent,string key,string label){var box=new System.Windows.Controls.Primitives.ToggleButton{Name=key,IsChecked=B(key),Style=(Style)FindResource("LightSwitch")};box.Click+=(_,_)=>{if(building)return;Set(key,box.IsChecked==true);Build();};Row(parent,label,box);}
 void InputMode(W.Panel parent){var panel=new W.StackPanel{Orientation=W.Orientation.Horizontal};for(int i=0;i<2;i++){int mode=i;var radio=new W.RadioButton{Name="CalibPointInput"+i,Content=i==0?"点":"X/Y",GroupName="NPointInputMode",IsChecked=I("CalibPointInput")==i,Style=(Style)FindResource("LightRadio"),Margin=new Thickness(0,0,16,0)};radio.Checked+=(_,_)=>{if(building)return;Set("CalibPointInput",mode);Build();};panel.Children.Add(radio);}Row(parent,"标定点输入",panel);}
 string InputLabel(string key)=>context.SubscriptionLabel?.Invoke(key,false)??"";
 void Input(W.Panel parent,string key,string label,bool text=false){var panel=new W.DockPanel();var link=Button("↗",()=>{context.PickSubscription?.Invoke(this,key,false,text?DataKind.Text:DataKind.NumberArray);Build();},"Subscribe"+key);W.DockPanel.SetDock(link,W.Dock.Right);panel.Children.Add(link);var edit=new W.TextBox{Name="Input"+key,Height=28,VerticalContentAlignment=VerticalAlignment.Center,Text=text?context.InputText?.Invoke(key)??InputLabel(key):context.InputNumbers?.Invoke(key) is {} numbers?string.Join(", ",numbers.Select(v=>v.ToString("G9",CultureInfo.InvariantCulture))):InputLabel(key)};edit.LostKeyboardFocus+=(_,_)=>{if(building||closed)return;Safe(()=>{if(text)context.SetInputText?.Invoke(key,string.IsNullOrEmpty(edit.Text)?null:edit.Text);else context.SetInputNumbers?.Invoke(key,string.IsNullOrWhiteSpace(edit.Text)?null:edit.Text.Split([',','，',';'],StringSplitOptions.RemoveEmptyEntries).Select(s=>double.Parse(s,CultureInfo.InvariantCulture)).ToArray());Build();});};panel.Children.Add(edit);Row(parent,label,panel);}
 void PairInput(W.Panel parent,string x,string y,string caption){var field=Button(string.IsNullOrEmpty(InputLabel(x))&&string.IsNullOrEmpty(InputLabel(y))?"请选择":InputLabel(x)+" / "+InputLabel(y),()=>{var dialog=new Window{Title=caption,Owner=this,Width=420,Height=180,WindowStartupLocation=WindowStartupLocation.CenterOwner};var rows=new W.StackPanel{Margin=new Thickness(16)};void Coordinate(string key,string label){var panel=new W.DockPanel();var select=Button("↗",()=>{context.PickSubscription?.Invoke(dialog,key,false,DataKind.NumberArray);Build();});W.DockPanel.SetDock(select,W.Dock.Right);panel.Children.Add(select);var edit=new W.TextBox{Text=context.InputNumbers?.Invoke(key) is {} numbers?string.Join(",",numbers.Select(v=>v.ToString(CultureInfo.InvariantCulture))):"",Height=27};edit.LostKeyboardFocus+=(_,_)=>Safe(()=>context.SetInputNumbers?.Invoke(key,string.IsNullOrWhiteSpace(edit.Text)?null:edit.Text.Split(',').Select(v=>double.Parse(v,CultureInfo.InvariantCulture)).ToArray()));panel.Children.Add(edit);Row(rows,label,panel);}Coordinate(x,"X");Coordinate(y,"Y");rows.Children.Add(Button("确定",()=>dialog.Close()));dialog.Content=rows;dialog.ShowDialog();Build();},"InputPair"+x);field.HorizontalContentAlignment=System.Windows.HorizontalAlignment.Left;Row(parent,caption,field);}
 bool PhysicalVisible()=>I("CalibPointGet")==0&&string.IsNullOrEmpty(InputLabel("WorldRotateAngle"))&&string.IsNullOrEmpty(InputLabel("PhysicalPointX"))&&string.IsNullOrEmpty(InputLabel("PhysicalPointY"));
 void Build(){int selected=tabs.SelectedIndex;building=true;try{tabs.Items.Clear();var basic=Page("NPointBasic","基本参数");Header(basic,"标定参数");Choice(basic,"CalibPointGet","标定点获取","触发获取","手动输入");if(I("CalibPointGet")==0){InputMode(basic);if(I("CalibPointInput")==0){PairInput(basic,"ImagePointX","ImagePointY","图像坐标");PairInput(basic,"PhysicalPointX","PhysicalPointY","物理坐标");}else{Input(basic,"ImagePointX","图像坐标 X");Input(basic,"ImagePointY","图像坐标 Y");Input(basic,"PhysicalPointX","物理坐标 X");Input(basic,"PhysicalPointY","物理坐标 Y");}Input(basic,"ImageRotateAngle","图像旋转角度");Input(basic,"WorldRotateAngle","物理旋转角度");}
  Number(basic,"CalibPointTotalNum","平移次数");Number(basic,"RotPointTotalNum","旋转次数");Row(basic,"标定点",Button("编辑",()=>{new NPointTableWindow(this,values,Apply,()=>ClearPoints()).ShowDialog();Build();},"EditNPointTable"));if(I("CalibPointGet")==0){Toggle(basic,"TeachEnable","示教使能");if(B("TeachEnable")){Input(basic,"Trigger","输入字符",true);Input(basic,"TeachFlagInput","示教标识",true);}}
  if(PhysicalVisible()){Header(basic,"物理坐标参数");Number(basic,"BasePointX","基准坐标 X");Number(basic,"BasePointY","基准坐标 Y");Number(basic,"MoveAlignX","X向移动步长");Number(basic,"MoveAlignY","Y向移动步长");Choice(basic,"MoveFirstType","移动优先","X优先","Y优先");Number(basic,"ChangeDirectionMoveTime","换向次数");if(I("RotPointTotalNum")>0){Number(basic,"BaseAngle","基准角度");Number(basic,"MoveAngle","旋转步长");}Toggle(basic,"UseRelativeCoordinates","使用相对坐标");if(B("UseRelativeCoordinates"))Number(basic,"CalibOrigin","标定原点",true);}
  Header(basic,"标定文件");Toggle(basic,"RefreshFileEnable","更新标定文件");Row(basic,"生成标定文件",Button("保存…",()=>SaveFile(),"SaveNPointCalibration"));var pathPanel=new W.DockPanel();var browse=Button("…",()=>{var dialog=new Microsoft.Win32.OpenFileDialog{Filter="标定文件|*.xml",CheckFileExists=true};if(dialog.ShowDialog(this)==true){Set("CalibPathName",dialog.FileName);Build();}},"BrowseNPointCalibration");W.DockPanel.SetDock(browse,W.Dock.Right);pathPanel.Children.Add(browse);var path=new W.TextBox{Name="CalibPathName",Text=values["CalibPathName"].GetString()??"",Height=28};path.LostKeyboardFocus+=(_,_)=>{if(!building)Set("CalibPathName",path.Text);};pathPanel.Children.Add(path);Row(basic,"文件路径",pathPanel);
  var run=Page("NPointRun","运行参数");Header(run,"运行参数");Choice(run,"CameraMode","相机模式","相机静止上相机位","相机静止下相机位","相机运动");Choice(run,"HomoFreedom","自由度","缩放、旋转、纵横比、倾斜、平移及透视","缩放、旋转、纵横比、倾斜及平移","缩放、旋转及平移");var expand=new W.CheckBox{Name="NPointAdvanced",Content="高级参数",IsChecked=advanced,Margin=new Thickness(0,12,0,8)};expand.Click+=(_,_)=>{advanced=expand.IsChecked==true;Build();};run.Children.Add(expand);if(advanced){Choice(run,"WeightFun","权重函数","最小二乘","Huber","Tukey");if(I("WeightFun") is 2 or 3)Number(run,"WeightFactor","权重系数");}run.Children.Add(Button("清空标定点",()=>ClearPoints(),"ClearNPointPoints"));tabs.Items.Add(new W.TabItem{Name="NPointResult",Header="结果显示",Content=new W.ScrollViewer{Content=result}});tabs.SelectedIndex=selected>=0&&selected<tabs.Items.Count?selected:0;
 }finally{building=false;}}
 void ClearPoints(){for(int i=0;i<32;i++)foreach(string key in new[]{"ImagePointX","ImagePointY","WorldPointX","WorldPointY","DeltaAngle"})values[key+i]=JsonSerializer.SerializeToElement(0d);Set("ClearRevision",checked(I("ClearRevision")+1));plugin.Clear(context);}
 void SaveFile(){var dialog=new Microsoft.Win32.SaveFileDialog{Filter="标定文件|*.xml",DefaultExt=".xml"};if(dialog.ShowDialog(this)==true)Safe(()=>{plugin.Export(context with{Node=context.Node with{Parameters=values}},dialog.FileName);Set("CalibPathName",dialog.FileName);Build();});}
 void Safe(Action action){try{action();}catch(Exception ex){System.Windows.MessageBox.Show(this,ex.Message,"N点标定");}}
 async Task Execute(){if(running||closed)return;running=true;once.IsEnabled=false;try{var record=await context.Run(values.ToDictionary(p=>p.Key,p=>p.Value.Clone()));result.Text=string.Join(Environment.NewLine,record.Outputs.Select(p=>p.Key+": "+(p.Value.Kind==DataKind.NumberArray?string.Join(", ",p.Value.As<IReadOnlyList<double>>().Select(v=>v.ToString("G7",CultureInfo.InvariantCulture))):p.Value.Kind==DataKind.Calibration?"3×3 图像→物理坐标矩阵":Convert.ToString(p.Value.Value,CultureInfo.InvariantCulture))));}catch(Exception e){continuous=false;System.Windows.MessageBox.Show(this,e.Message,"执行失败");}finally{running=false;once.IsEnabled=!continuous;}}
}

public sealed class NPointTableWindow:Window {
 readonly Dictionary<string,JsonElement> values;readonly Action apply;readonly W.DataGrid table=new(){AutoGenerateColumns=false,CanUserAddRows=false,CanUserDeleteRows=false,CanUserSortColumns=false,CanUserReorderColumns=false,CanUserResizeRows=false,HeadersVisibility=W.DataGridHeadersVisibility.Column,ColumnHeaderHeight=30,RowHeight=30,MinColumnWidth=20,MaxColumnWidth=150,BorderThickness=new Thickness(0),GridLinesVisibility=W.DataGridGridLinesVisibility.Vertical,VerticalGridLinesBrush=new SolidColorBrush(Color.FromRgb(213,213,213)),RowBackground=new SolidColorBrush(Color.FromRgb(235,235,235)),AlternatingRowBackground=new SolidColorBrush(Color.FromRgb(224,224,224)),Foreground=new SolidColorBrush(Color.FromRgb(132,132,132)),FontSize=14,Margin=new Thickness(14,20,4,10)};
 public sealed class PointRow {public int ID{get;init;}public string ImageX{get;set;}="0.000";public string ImageY{get;set;}="0.000";public string WorldX{get;set;}="0.000";public string WorldY{get;set;}="0.000";public string Angle{get;set;}="0.000";}
 public NPointTableWindow(Window owner,Dictionary<string,JsonElement> values,Action apply,Action clear){Owner=owner;this.values=values;this.apply=apply;Title="编辑标定点";Width=493;Height=399;WindowStartupLocation=WindowStartupLocation.CenterOwner;var headerStyle=new Style(typeof(System.Windows.Controls.Primitives.DataGridColumnHeader));headerStyle.Setters.Add(new Setter(W.Control.BackgroundProperty,new SolidColorBrush(Color.FromRgb(166,166,166))));headerStyle.Setters.Add(new Setter(W.Control.ForegroundProperty,new SolidColorBrush(Color.FromRgb(70,70,70))));headerStyle.Setters.Add(new Setter(W.Control.HorizontalContentAlignmentProperty,System.Windows.HorizontalAlignment.Center));table.ColumnHeaderStyle=headerStyle;var cellStyle=new Style(typeof(W.TextBlock));cellStyle.Setters.Add(new Setter(W.TextBlock.TextAlignmentProperty,TextAlignment.Center));cellStyle.Setters.Add(new Setter(W.TextBlock.VerticalAlignmentProperty,VerticalAlignment.Center));table.Resources.Add(typeof(W.TextBlock),cellStyle);var grid=new W.DockPanel();var buttons=new W.StackPanel{Orientation=W.Orientation.Horizontal,HorizontalAlignment=System.Windows.HorizontalAlignment.Right,Margin=new Thickness(0,8,0,0)};W.DockPanel.SetDock(buttons,W.Dock.Bottom);grid.Children.Add(buttons);void Do(Action action){try{table.CommitEdit();table.CommitEdit();action();}catch(Exception ex){System.Windows.MessageBox.Show(this,ex.Message,Title);}}
  void Button(string text,Action action){var b=new W.Button{Content=text,MinWidth=66,Height=25,Margin=new Thickness(3,0,0,0)};b.Click+=(_,_)=>Do(action);buttons.Children.Add(b);}
  Button("导出",()=>{Commit();var dialog=new Microsoft.Win32.SaveFileDialog{Filter="txt|*.txt"};if(dialog.ShowDialog(this)==true){System.IO.File.WriteAllText(dialog.FileName,NPointFile.ExportPointRows(table.Items.OfType<PointRow>().Select(p=>(IReadOnlyList<string>)new[]{p.ImageX,p.ImageY,p.WorldX,p.WorldY,p.Angle})));}});Button("导入",()=>{var dialog=new Microsoft.Win32.OpenFileDialog{Filter="txt|*.txt"};if(dialog.ShowDialog(this)==true){try{NPointFile.ImportPointText(System.IO.File.ReadAllText(dialog.FileName),Count,(i,row)=>{for(int a=0;a<5;a++)values[Keys[a]+i]=JsonSerializer.SerializeToElement((double)row[a]);apply();});}finally{Load();}}});Button("清空标定点",()=>{clear();Load();});Button("确定",()=>{Commit();Close();});
  foreach(var pair in new[]{("ID","ID"),("图像坐标X","ImageX"),("图像坐标Y","ImageY"),("物理坐标X","WorldX"),("物理坐标Y","WorldY"),("角度","Angle")}){var editorStyle=new Style(typeof(W.TextBox));editorStyle.Setters.Add(new Setter(W.TextBox.MaxLengthProperty,pair.Item2.StartsWith("World",StringComparison.Ordinal)?15:10));table.Columns.Add(new W.DataGridTextColumn{Header=pair.Item1,Binding=new System.Windows.Data.Binding(pair.Item2),EditingElementStyle=editorStyle,IsReadOnly=pair.Item2=="ID",Width=new W.DataGridLength(1,W.DataGridLengthUnitType.Star)});}var deleteFactory=new FrameworkElementFactory(typeof(W.Button));deleteFactory.SetValue(W.Button.ContentProperty,"×");deleteFactory.AddHandler(W.Button.ClickEvent,new RoutedEventHandler((sender,_)=>Do(()=>{if(((W.Button)sender).DataContext is not PointRow row)return;Commit();int trans=values["CalibPointTotalNum"].GetInt32(),rot=values["RotPointTotalNum"].GetInt32();if(trans==4&&rot==0)throw new InvalidOperationException("至少保留四个平移点。");int total=trans+rot;if(row.ID<trans&&trans>4)values["CalibPointTotalNum"]=JsonSerializer.SerializeToElement(trans-1);else values["RotPointTotalNum"]=JsonSerializer.SerializeToElement(rot-1);for(int i=row.ID;i<total-1;i++)foreach(string key in Keys)values[key+i]=values[key+(i+1)].Clone();apply();Load();})));table.Columns.Add(new W.DataGridTemplateColumn{Header="",Width=28,CellTemplate=new DataTemplate{VisualTree=deleteFactory}});table.CellEditEnding+=(_,_)=>Dispatcher.BeginInvoke(()=>{try{Commit();}catch{}});grid.Children.Add(table);Content=grid;Load();
 }
 static readonly string[] Keys=["ImagePointX","ImagePointY","WorldPointX","WorldPointY","DeltaAngle"];
 int Count=>values["CalibPointTotalNum"].GetInt32()+values["RotPointTotalNum"].GetInt32();
 float[,] Points(){var points=new float[32,6];for(int i=0;i<Count;i++)for(int a=0;a<5;a++)points[i,a]=(float)values[Keys[a]+i].GetDouble();return points;}
 void Load(){table.ItemsSource=Enumerable.Range(0,Count).Select(i=>new PointRow{ID=i,ImageX=values[Keys[0]+i].GetDouble().ToString("F3",CultureInfo.InvariantCulture),ImageY=values[Keys[1]+i].GetDouble().ToString("F3",CultureInfo.InvariantCulture),WorldX=values[Keys[2]+i].GetDouble().ToString("F3",CultureInfo.InvariantCulture),WorldY=values[Keys[3]+i].GetDouble().ToString("F3",CultureInfo.InvariantCulture),Angle=values[Keys[4]+i].GetDouble().ToString("F3",CultureInfo.InvariantCulture)}).ToArray();}
 void Commit(){foreach(var row in table.Items.OfType<PointRow>()){var fields=new[]{row.ImageX,row.ImageY,row.WorldX,row.WorldY,row.Angle};for(int axis=0;axis<5;axis++){float value=float.Parse(fields[axis],CultureInfo.InvariantCulture);if(!float.IsFinite(value))throw new InvalidOperationException("标定点必须为有限数值。");values[Keys[axis]+row.ID]=JsonSerializer.SerializeToElement((double)value);}}apply();}
